package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
)

type DateRec struct { // 01 DATE-REC, 12 bytes
	DtId   string // PIC X(4) @0 len=4
	DtYyyy int64  // PIC 9(4) @4 len=4
	DtMm   int64  // PIC 9(2) @8 len=2
	DtDd   int64  // PIC 9(2) @10 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"  // PIC X len=1 = "N"
var WsLeapFlag string = "N" // PIC X len=1 = "N"
var WsQ int64 = 0           // PIC 9(4) len=4 = 0
var WsR4 int64 = 0          // PIC 9(3) len=3 = 0
var WsR100 int64 = 0        // PIC 9(3) len=3 = 0
var WsR400 int64 = 0        // PIC 9(3) len=3 = 0
var WsMaxDay int64 = 0      // PIC 99 len=2 = 0
var WsValid int64 = 0       // PIC 99 len=2 = 0
var WsBadMonth int64 = 0    // PIC 99 len=2 = 0
var WsBadDay int64 = 0      // PIC 99 len=2 = 0

var curRec DateRec
var fileRecs []string
var fileIdx int

func pow10(n int) int64 {
	var p int64 = 1
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func storePic(v int64, digits int) int64 {
	mod := pow10(digits)
	r := v % mod
	if r < 0 {
		r = -r
	}
	return r
}

func fmtPic9(v int64, digits int) string {
	mod := pow10(digits)
	vv := v % mod
	if vv < 0 {
		vv = -vv
	}
	// zero padded to digits
	format := "%0" + strconv.Itoa(digits) + "d"
	return fmt.Sprintf(format, vv)
}

func parseNumericField(s string) int64 {
	trimmed := strings.TrimSpace(s)
	if trimmed == "" {
		return 0
	}
	v, err := strconv.ParseInt(trimmed, 10, 64)
	if err == nil {
		return v
	}
	// fallback: keep only digits
	filtered := ""
	for _, c := range trimmed {
		if c >= '0' && c <= '9' {
			filtered += string(c)
		} else if c == '-' || c == '+' {
			filtered += string(c)
		}
	}
	if filtered == "" || filtered == "-" || filtered == "+" {
		return 0
	}
	v2, err2 := strconv.ParseInt(filtered, 10, 64)
	if err2 != nil {
		return 0
	}
	return v2
}

func isInputDone() bool { return WsEofFlag == "Y" }
func isLeap() bool      { return WsLeapFlag == "Y" }

func cobolDisplay(parts ...string) {
	out := strings.Join(parts, "")
	fmt.Fprintln(os.Stdout, out)
}

// Paragraphs

func MAINPARA() {
	if err := openDateFile(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	// CLOSE DATE-FILE (no-op, file already closed)
	cobolDisplay("VALID: ", fmtPic9(WsValid, 2), " BAD MONTH: ", fmtPic9(WsBadMonth, 2), " BAD DAY: ", fmtPic9(WsBadDay, 2))
}

func openDateFile() error {
	f, err := os.Open("input.dat")
	if err != nil {
		return err
	}
	defer f.Close()
	reader := bufio.NewReader(f)
	var recs []string
	for {
		line, err := reader.ReadString('\n')
		isEOF := err == io.EOF
		if err != nil && err != io.EOF {
			return err
		}
		hasNL := false
		if strings.HasSuffix(line, "\n") {
			hasNL = true
			line = line[:len(line)-1]
			if strings.HasSuffix(line, "\r") {
				line = line[:len(line)-1]
			}
		} else {
			// last line without newline, strip trailing \r if present (CRLF without LF not possible)
			if strings.HasSuffix(line, "\r") {
				line = line[:len(line)-1]
			}
		}
		// If we are at EOF and line is empty and we had no data (empty file), don't add an extra record
		// The ReadString at EOF returns the last line even without newline.
		// For a file ending with newline, the last ReadString after the final newline will be EOF with empty line - we must not add.
		if hasNL {
			recs = append(recs, line)
			if isEOF {
				break
			}
		} else {
			if len(line) > 0 || !isEOF {
				// line may be empty but it's a record if it's not the artificial trailing empty after newline
				// For non-newline terminated file, len>0 is the last record; if file is empty len==0 and isEOF we add nothing
				if len(line) > 0 || len(recs) == 0 && line == "" && !isEOF {
					recs = append(recs, line)
				} else if len(line) > 0 {
					recs = append(recs, line)
				} else {
					// empty file: no records
				}
			} else {
				// empty line at EOF with no data - nothing
			}
			break
		}
		if isEOF {
			break
		}
	}
	// Alternative simpler handling for files that were read via ReadFile and splitted incorrectly:
	// The above logic already handles correctly.
	fileRecs = recs
	fileIdx = 0
	return nil
}

func READPARA() {
	if fileIdx < len(fileRecs) {
		raw := fileRecs[fileIdx]
		fileIdx++
		// pad/truncate to 12
		if len(raw) < 12 {
			raw = raw + strings.Repeat(" ", 12-len(raw))
		} else if len(raw) > 12 {
			raw = raw[:12]
		}
		id := raw[0:4]
		yStr := raw[4:8]
		mStr := raw[8:10]
		dStr := raw[10:12]
		curRec.DtId = id
		curRec.DtYyyy = parseNumericField(yStr)
		curRec.DtMm = parseNumericField(mStr)
		curRec.DtDd = parseNumericField(dStr)
	} else {
		WsEofFlag = "Y"
	}
}

func PROCESSPARA() {
	LEAPPARA()
	if curRec.DtMm < 1 || curRec.DtMm > 12 {
		WsBadMonth = storePic(WsBadMonth+1, 2)
		cobolDisplay(curRec.DtId, " BAD MONTH ", fmtPic9(curRec.DtMm, 2))
	} else {
		DAYSPARA()
		if curRec.DtDd < 1 || curRec.DtDd > WsMaxDay {
			WsBadDay = storePic(WsBadDay+1, 2)
			cobolDisplay(curRec.DtId, " BAD DAY ", fmtPic9(curRec.DtDd, 2), " MAX ", fmtPic9(WsMaxDay, 2))
		} else {
			WsValid = storePic(WsValid+1, 2)
			cobolDisplay(curRec.DtId, " VALID ", fmtPic9(curRec.DtYyyy, 4), "-", fmtPic9(curRec.DtMm, 2), "-", fmtPic9(curRec.DtDd, 2))
		}
	}
	READPARA()
}

func LEAPPARA() {
	// DIVIDE DT-YYYY BY 4 GIVING WS-Q REMAINDER WS-R4
	WsQ = storePic(curRec.DtYyyy/4, 4)
	WsR4 = storePic(curRec.DtYyyy%4, 3)
	// DIVIDE DT-YYYY BY 100 GIVING WS-Q REMAINDER WS-R100
	WsQ = storePic(curRec.DtYyyy/100, 4)
	WsR100 = storePic(curRec.DtYyyy%100, 3)
	// DIVIDE DT-YYYY BY 400 GIVING WS-Q REMAINDER WS-R400
	WsQ = storePic(curRec.DtYyyy/400, 4)
	WsR400 = storePic(curRec.DtYyyy%400, 3)

	if WsR4 == 0 && (WsR100 != 0 || WsR400 == 0) {
		WsLeapFlag = "Y"
	} else {
		WsLeapFlag = "N"
	}
}

func DAYSPARA() {
	switch curRec.DtMm {
	case 2:
		if isLeap() {
			WsMaxDay = storePic(29, 2)
		} else {
			WsMaxDay = storePic(28, 2)
		}
	case 4, 6, 9, 11:
		WsMaxDay = storePic(30, 2)
	default:
		WsMaxDay = storePic(31, 2)
	}
}

func main() {
	MAINPARA()
}
